// Two-case tagged type for a 64-bit date-time value.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum DateTime64 {
    Nat,
    Valid(i64),
}

pub fn isnat(x: Vec<DateTime64>) -> Vec<bool> {
    // Preserve order and length; true exactly for Nat, false for any Valid(_).
    x.into_iter()
        .map(|dt| matches!(dt, DateTime64::Nat))
        .collect()
}

